import{V as e,et as t,ht as n,tt as r}from"./chunks/framework.5U8vtJuw.js";import"./chunks/assets.M7-Gz8W6.js";var i=JSON.parse(`{"title":"Step 3: Create service category and service vendor","description":"","frontmatter":{"permalink":"/docs/getting-started/first-steps/step3/"},"headers":[],"relativePath":"docs/getting-started/first-steps/step3-create-service-vendor.md","filePath":"docs/getting-started/first-steps/step3-create-service-vendor.md"}`),a={name:`docs/getting-started/first-steps/step3-create-service-vendor.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="step-3-create-service-category-and-service-vendor" tabindex="-1">Step 3: Create service category and service vendor <a class="header-anchor" href="#step-3-create-service-category-and-service-vendor" aria-label="Permalink to “Step 3: Create service category and service vendor”">​</a></h1><p>Since your device is now ready for service deployment, we need to create a service offering that can be deployed on your device. Therefore, we need to create a service category and a service vendor in the <code>Admin</code> section. In case you do not see the <code>Admin</code> section at the bottom of the left menu:</p><p><img src="/slm/img/figures/first-steps/first-steps-step3-activated-admin-section.png" alt="first-steps-step3-activated-admin-section" data-zoomable="true"></p><p>...please follow the instructions in the <a href="#make-default-user-a-admin">next section</a> to make the default user an admin first. Otherwise, continue with the instructions in this <a href="#create-service-vendor">section</a>.</p><h2 id="make-default-user-a-admin" tabindex="-1">Make default user a admin <a class="header-anchor" href="#make-default-user-a-admin" aria-label="Permalink to “Make default user a admin”">​</a></h2><p>In case you do not see the <code>Admin</code> section at the bottom of the left menu, you need to make the default user <code>fabos</code> an admin first. To do so, you have to log into SLM&#39;s keycloak instance (e.g. <a href="https://myhost.local/auth" target="_blank" rel="noreferrer">https://myhost.local/auth</a>) with the default credentials (<code>admin</code> / <code>password</code>):</p><p><img src="/slm/img/figures/first-steps/first-steps-step3-login-keycloak.png" alt="first-steps-step3-login-keycloak" data-zoomable="true"></p><div class="info custom-block"><p class="custom-block-title">GO TO</p><p>Manage realms</p></div><p>...and select the <code>fabos</code> realm:</p><p><img src="/slm/img/figures/first-steps/first-steps-step3-select-keycloak-realm.png" alt="first-steps-step3-select-keycloak-realm" data-zoomable="true"></p><div class="info custom-block"><p class="custom-block-title">GO TO</p><p>Users</p></div><p>... and select the user <code>fabos</code>:</p><p><img src="/slm/img/figures/first-steps/first-steps-step3-select-fabos-user.png" alt="first-steps-step3-select-fabos-user" data-zoomable="true"></p><div class="info custom-block"><p class="custom-block-title">GO TO</p><p>Assign role &gt; realm roles</p></div><p>... select <code>slm-admin</code> and confirm with <code>Assign</code>:</p><p><img src="/slm/img/figures/first-steps/first-steps-step3-assign-admin-role.png" alt="first-steps-step3-assign-admin-role" data-zoomable="true"></p><p>Logout from keyloak:</p><p><img src="/slm/img/figures/first-steps/first-steps-step3-logout-keycloak.png" alt="first-steps-step3-logout-keycloak" data-zoomable="true"></p><h2 id="create-service-vendor" tabindex="-1">Create Service Vendor <a class="header-anchor" href="#create-service-vendor" aria-label="Permalink to “Create Service Vendor”">​</a></h2><div class="info custom-block"><p class="custom-block-title">GO TO</p><p>Admin &gt; Service Vendors</p></div><p>... and click on <code>Add Service Vendor</code> button in the lower left corner:</p><p><img src="/slm/img/figures/first-steps/first-steps-step3-service-vendor-overview.png" alt="first-steps-step3-service-vendor-overview" data-zoomable="true"></p><p>Enter a name, description and a logo (optional) for your service vendor and click <code>Create</code>:</p><p><img src="/slm/img/figures/first-steps/first-steps-step3-new-service-vendor-form.png" alt="first-steps-step3-new-service-vendor-form" data-zoomable="true"></p><p>Make sure to add the user <code>fabos</code> as developer to your service vendor to be able to create and manage service offerings for this service vendor. To do so, select your created service vendor:</p><p><img src="/slm/img/figures/first-steps/first-steps-step3-select-new-service-vendor.png" alt="first-steps-step3-select-new-service-vendor" data-zoomable="true"></p><p>click on <code>Add developer</code> field, select the user <code>fabos</code> from the dropdown</p><p><img src="/slm/img/figures/first-steps/first-steps-step3-select-fabos-user-as-developer.png" alt="first-steps-step3-select-fabos-user-as-developer.png" data-zoomable="true"></p><p>...and click <code>SAVE</code>.</p><h2 id="create-service-offering-category" tabindex="-1">Create Service Offering Category <a class="header-anchor" href="#create-service-offering-category" aria-label="Permalink to “Create Service Offering Category”">​</a></h2><div class="info custom-block"><p class="custom-block-title">GO TO</p><p>Admin &gt; Service Categories</p></div><p>... and add a new service category by clicking on the <code>Add Service Category</code> button in the lower left corner in case you do not have any service category yet or want to add another one:</p><p><img src="/slm/img/figures/first-steps/first-steps-step3-service-category-overview.png" alt="first-steps-step3-service-category-overview" data-zoomable="true"></p><p>Enter a name for your service category and click <code>Create</code>:</p><p><img src="/slm/img/figures/first-steps/first-steps-step3-service-category-form.png" alt="first-steps-step3-service-category-form" data-zoomable="true"></p>`,35)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};